function terrain(x){
  let y=groundY()-Math.min(210,x*.018)+Math.sin(x*.0032)*12+Math.sin(x*.009)*5;
  const idx=Math.max(0,Math.floor((x-500)/700));
  for(let i=Math.max(0,idx-1);i<=idx+1;i++){
    const g=gapInfo(i),pre=g.start-105,post=g.end+105;
    if(x>=pre&&x<g.start){const t=(x-pre)/(g.start-pre);y=groundY()-Math.min(210,x*.018)-82*t-22*Math.sin(t*Math.PI);}
    else if(x>=g.start&&x<=g.end)return null;
    else if(x>g.end&&x<post){const t=(x-g.end)/(post-g.end);y=groundY()-Math.min(210,x*.018)-64*(1-t)-18*Math.sin(t*Math.PI);}
  }
  const jumpIndex=Math.floor((x-1700)/2600);
  if(jumpIndex>=0){const center=1700+jumpIndex*2600+rand(jumpIndex+31)*900,dist=x-center;
    if(Math.abs(dist)<150){const t=1-Math.abs(dist)/150;y-=Math.pow(t,2)*95;}
  }
  return y;
}

